<?php
class Reporte_abordaje extends CI_Controller{
 private $session_data=array();
 public function __construct(){parent::__construct();if(!$this->session->userdata('logged_in'))redirect('','refresh');$this->session_data=$this->session->userdata('logged_in');$this->load->model('Reporte_abordaje_model');$this->load->model('Sistema_model');$this->load->model('Parametro_model');if(!$this->Reporte_abordaje_model->usuario_tiene_rol((int)$this->session_data['usuario_id'],220))show_error('No tiene permiso para generar reportes de Transporte.',403,'Acceso denegado');}
 private function filtros(){ $d=trim((string)$this->input->get('desde',true));$h=trim((string)$this->input->get('hasta',true));if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$d))$d=date('Y-m-d');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$h))$h=date('Y-m-d');if($d>$h){$x=$d;$d=$h;$h=$x;}return array('desde'=>$d,'hasta'=>$h,'viaje_id'=>(int)$this->input->get('viaje_id',true),'solo_no_show'=>(int)$this->input->get('solo_no_show',true));}
 public function index(){ $f=$this->filtros();$p=$this->Parametro_model->get_parametros();$data['sistema']=$this->Sistema_model->get_sistema();$data['parametro']=isset($p[0])?$p[0]:$p;$data['filtros']=$f;$data['viajes']=$this->Reporte_abordaje_model->viajes($f);$data['resumen']=$this->Reporte_abordaje_model->resumen($f);$data['detalle']=$this->Reporte_abordaje_model->detalle($f);$data['page_title']='Reporte de abordaje';$data['_view']='reporte_transporte/abordaje';$this->load->view('layouts/main',$data);}
 public function csv(){ $f=$this->filtros();$rs=$this->Reporte_abordaje_model->detalle($f);header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="abordaje_'.$f['desde'].'_'.$f['hasta'].'.csv"');echo "\xEF\xBB\xBF";$x=fopen('php://output','w');fputcsv($x,array('Viaje','Pasaje','Pasajero','Documento','Asiento','Estado abordaje','Fecha abordaje','Hora abordaje','Terminal'),';');foreach($rs as $r)fputcsv($x,array($r['viaje'],$r['pasaje_numero'],$r['pasajero'],$r['documento'],$r['asiento'],$r['estado_abordaje'],$r['abordaje_fecha'],$r['abordaje_hora'],$r['terminal']),';');fclose($x);exit;}
}
